// Entry point standard C/C++ signature
int main(int argc, char *argv[]) {

    // argc: count of command line arguments
    // argv: array of C strings (argv[0] is program name)

    /* Execution begins here */

    // Use arguments
    if (argc == 1) {
        return 1; // Indicate failure (EXIT_FAILURE)
    }

    return 0; // Indicate success (EXIT_SUCCESS)
}

// Alternative (no arguments required):
// int main() { return 0; }
// C++ requires return 0 if omitted, C does not.
